extern "C" void OhplA1HostCall(unsigned op, const OhplA1Arg *a, size_t n, OhplA1Arg *r)
{
	if(op == kOhplA1OpWarning)
	{
		Warning("%s", string(OhplA1Str(a[0])).c_str());
		return;
	}
	if(op < sizeof(ohpl_a1h::kOps) / sizeof(ohpl_a1h::kOps[0])) ohpl_a1h::kOps[op](a, r);
}
